CREATE TABLE IF NOT EXISTS delivery_consent (environment TEXT NOT NULL, client_id TEXT NOT NULL, recipient_ref TEXT NOT NULL, channel TEXT NOT NULL, consent_status TEXT NOT NULL CHECK (consent_status IN ('granted','revoked','unknown')), consent_ref TEXT, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, recipient_ref, channel));
CREATE TABLE IF NOT EXISTS delivery_attempts (environment TEXT NOT NULL, client_id TEXT NOT NULL, submission_id TEXT NOT NULL, channel TEXT NOT NULL, recipient_ref TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('blocked','queued','sent','failed')), reason_code TEXT NOT NULL, correlation_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, submission_id, channel));
